#include <zephyr/ztest.h>
#include <zephyr/kernel.h>

#define STACK_SIZE 10
K_STACK_DEFINE(stack, STACK_SIZE);

static void test_stack_push_full(void)
{
	_stack_word_t data_tmp;
	int num_pushes = STACK_SIZE;

#ifdef CONFIG_USERSPACE
	/* When CONFIG_USERSPACE is enabled, k_stack might have an extra word
	 * for internal bookkeeping, making its effective capacity STACK_SIZE + 1.
	 * Adjust the number of pushes accordingly.
	 */
	num_pushes++;
#endif

	/* Fill the stack */
	for (int i = 0; i < num_pushes; i++) {
		k_stack_push(&stack, (void *)(uintptr_t)i);
	}

	/* The next push should fail */
	zassert_equal(k_stack_push(&stack, data_tmp), -ENOMEM,
		      "k_stack_push did not return -ENOMEM when stack is full");
}

static void test_stack_pop_empty(void)
{
	_stack_word_t data_tmp;

	/* Pop from an empty stack should fail */
	zassert_equal(k_stack_pop(&stack, &data_tmp, K_NO_WAIT), -ENOMEM,
		      "k_stack_pop did not return -ENOMEM when stack is empty");
}

static void test_stack_pop_timeout(void)
{
	_stack_word_t data_tmp;

	/* Pop from an empty stack with timeout should fail */
	zassert_equal(k_stack_pop(&stack, &data_tmp, K_MSEC(10)), -EAGAIN,
		      "k_stack_pop did not return -EAGAIN when stack is empty with timeout");
}

void test_main(void)
{
	ztest_test_suite(stack_fail_test,
		ztest_unit_test(test_stack_push_full),
		ztest_unit_test(test_stack_pop_empty),
		ztest_unit_test(test_stack_pop_timeout)
	);
	ztest_run_test_suite(stack_fail_test);
}
